alter table public.songs add column if not exists chart_rank integer;
alter table public.songs add column if not exists chart_source text;
alter table public.songs add column if not exists chart_updated_at timestamptz;
create unique index if not exists songs_provider_track_unique_idx on public.songs(provider_track_id);

on conflict(slug) do update set name=excluded.name,country=excluded.country,featured=excluded.featured,active=true;

on conflict(provider_track_id) do update set title=excluded.title,artist_name=excluded.artist_name,artist_id=excluded.artist_id,genre_id=excluded.genre_id,thumbnail_url=excluded.thumbnail_url,duration_seconds=excluded.duration_seconds,is_featured=excluded.is_featured,is_honduras_hit=excluded.is_honduras_hit,chart_rank=excluded.chart_rank,chart_source=excluded.chart_source,chart_updated_at=excluded.chart_updated_at,active=true;
